function F($size,$style=[Drawing.FontStyle]::Regular){return New-Object Drawing.Font('Segoe UI',$size,$style)}
function PathRound($x,$y,$w,$h,$r){$p=New-Object Drawing.Drawing2D.GraphicsPath;$d=2*$r;$p.AddArc($x,$y,$d,$d,180,90);$p.AddArc($x+$w-$d,$y,$d,$d,270,90);$p.AddArc($x+$w-$d,$y+$h-$d,$d,$d,0,90);$p.AddArc($x,$y+$h-$d,$d,$d,90,90);$p.CloseFigure();return $p}
function FillR($g,$x,$y,$w,$h,$r,$c){$b=New-Object Drawing.SolidBrush($c);$p=PathRound $x $y $w $h $r;$g.FillPath($b,$p);$b.Dispose();$p.Dispose()}
function StrokeR($g,$x,$y,$w,$h,$r,$c,$width=1){$p=New-Object Drawing.Pen($c,$width);$q=PathRound $x $y $w $h $r;$g.DrawPath($p,$q);$p.Dispose();$q.Dispose()}
function T($g,$s,$x,$y,$w,$h,$size,$c,$style=[Drawing.FontStyle]::Regular){$b=New-Object Drawing.SolidBrush($c);$font=F $size $style;$fmt=New-Object Drawing.StringFormat;$fmt.Trimming=[Drawing.StringTrimming]::EllipsisCharacter;$g.DrawString($s,$font,$b,(New-Object Drawing.RectangleF($x,$y,$w,$h)),$fmt);$font.Dispose();$b.Dispose();$fmt.Dispose()}
function Line($g,$x1,$y1,$x2,$y2,$c,$width=1){$p=New-Object Drawing.Pen($c,$width);$g.DrawLine($p,$x1,$y1,$x2,$y2);$p.Dispose()}
function Pill($g,$s,$x,$y,$w,$color,$textColor){FillR $g $x $y $w 24 12 $color;T $g $s ($x+8) ($y+5) ($w-16) 15 10 $textColor ([Drawing.FontStyle]::Bold)}
function Header($g,$active,$label){$g.Clear($bg);Line $g 0 83 1600 83 $line 1;FillR $g 34 20 40 40 12 $teal;T $g 'x' 45 29 20 20 18 $white ([Drawing.FontStyle]::Bold);T $g 'RideShare' 84 27 180 26 20 $teal ([Drawing.FontStyle]::Bold);T $g 'Home' 760 34 60 18 13 $(if($active -eq 'Home'){$teal}else{$muted}) ([Drawing.FontStyle]::Bold);T $g 'Vehicles' 840 34 72 18 13 $(if($active -eq 'Vehicles'){$teal}else{$muted}) ([Drawing.FontStyle]::Bold);FillR $g 930 24 210 34 17 $white;StrokeR $g 930 24 210 34 17 $line 1;T $g 'Search vehicles' 952 33 160 18 12 $muted;T $g 'Dark' 1190 34 55 18 13 $muted;T $g $label 1280 34 110 18 13 $teal ([Drawing.FontStyle]::Bold);T $g 'Dashboard' 1412 34 100 18 13 $muted;T $g 'Logout' 1525 34 60 18 13 $muted}
function Footer($g,$figure,$note){T $g "$figure  |  Illustrative sample data" 34 861 600 18 10 $muted;T $g $note 650 861 915 18 10 $muted}
function NewScreen($active,$label,$title,$subtitle,$figure,$note){$bmp=New-Object Drawing.Bitmap $W,$H;$g=[Drawing.Graphics]::FromImage($bmp);$g.SmoothingMode=[Drawing.Drawing2D.SmoothingMode]::AntiAlias;$g.TextRenderingHint=[Drawing.Text.TextRenderingHint]::AntiAliasGridFit;Header $g $active $label;T $g $title 40 112 1100 42 27 $ink ([Drawing.FontStyle]::Bold);T $g $subtitle 40 157 1200 22 14 $muted;Footer $g $figure $note;return @($bmp,$g)}
function SaveScreen($arr,$name){$bmp=$arr[0];$g=$arr[1];$path=Join-Path $outDir $name;$bmp.Save($path,[Drawing.Imaging.ImageFormat]::Png);$g.Dispose();$bmp.Dispose();return $path}
function Shot($g,$path,$x,$y,$w,$h){$im=[Drawing.Image]::FromFile($path);$scale=[Math]::Min($w/$im.Width,$h/$im.Height);$dw=[int]($im.Width*$scale);$dh=[int]($im.Height*$scale);$dx=[int]($x+(($w-$dw)/2));$dy=[int]($y+(($h-$dh)/2));$g.DrawImage($im,$dx,$dy,$dw,$dh);$im.Dispose()}
function VehicleCard($g,$x,$y,$w,$name,$type,$price){FillR $g $x $y $w 174 10 $white;StrokeR $g $x $y $w 174 10 $line 1;FillR $g ($x+12) ($y+12) ($w-24) 68 8 ([Drawing.Color]::FromArgb(237,245,243));FillR $g ($x+62) ($y+40) 110 30 15 ([Drawing.Color]::FromArgb(191,216,210));Line $g ($x+52) ($y+72) ($x+188) ($y+72) $teal 4;T $g $name ($x+14) ($y+91) ($w-28) 20 13 $ink ([Drawing.FontStyle]::Bold);T $g $type ($x+14) ($y+116) ($w-28) 17 10 $muted;T $g $price ($x+14) ($y+143) 130 18 12 $teal ([Drawing.FontStyle]::Bold);Pill $g 'Available' ($x+$w-92) ($y+140) 78 $greenLight $green}
function Metric($g,$x,$y,$w,$title,$value,$detail,$accent){FillR $g $x $y $w 84 10 $white;StrokeR $g $x $y $w 84 10 $line 1;T $g $title ($x+12) ($y+10) ($w-24) 16 10 $muted;T $g $value ($x+12) ($y+31) ($w-24) 25 18 $accent ([Drawing.FontStyle]::Bold);T $g $detail ($x+12) ($y+62) ($w-24) 14 9 $muted}

